int def scoreAmount(double:amount) {
    if (amount >= 50000.0) {
        return 30;
    } else if (amount >= 20000.0) {
        return 20;
    } else if (amount >= 10000.0) {
        return 12;
    } else if (amount >= 5000.0) {
        return 6;
    } else {
        return 0;
    }
}


int def scoreVelocity(int:txnCount1h, double:txnAmount1h) {
    int score = 0;
    if (txnCount1h >= 10) {
        score = 25;
    } else if (txnCount1h >= 5) {
        score = 15;
    } else if (txnCount1h >= 3) {
        score = 8;
    }
    if (txnAmount1h >= 100000.0) {
        score = score + 15;
    } else if (txnAmount1h >= 50000.0) {
        score = score + 8;
    }
    if (score > 25) {
        score = 25;
    }
    return score;
}


