int def scoreDeviation(double:amount, double:historicalMaxAmount, int:accountAgeDays) {
    int score = 0;
    if (historicalMaxAmount > 0.0) {
        if (amount * 10 >= historicalMaxAmount * 50) {
            score = 15;
        } else if (amount * 10 >= historicalMaxAmount * 30) {
            score = 8;
        }
    }
    if (accountAgeDays < 7) {
        score = score + 15;
    }
    return score;
}


str def riskLevel(int:riskScore) {
    if (riskScore >= 75) {
        return "HIGH";
    } else if (riskScore >= 45) {
        return "MEDIUM";
    } else {
        return "LOW";
    }
}


str def fraudAction(str:riskLevel) {
    if (riskLevel == "HIGH") {
        return "BLOCK";
    } else if (riskLevel == "MEDIUM") {
        return "STEP_UP";
    } else {
        return "PASS";
    }
}


boolean def needAlert(str:riskLevel, boolean:overseas) {
    if (riskLevel == "HIGH") {
        return true;
    } else if (riskLevel == "MEDIUM" && overseas) {
        return true;
    } else {
        return false;
    }
}
